let {channel}=$props<{channel:string}>();let info=$derived(channels.find(c=>c.id===channel)!);let items=$derived(snapshot.items.filter(x=>x.channel===channel));let records=$derived(snapshot.activity.filter(x=>x.channel===channel));let conversation=$derived(channel==='discussions'||channel==='cr26-discussions');
</script>
